-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
pit_gp_gp_detail_ranked as (
    select
        gp_hk,
        effective_from,
        dense_rank() over (partition by gp_hk order by hashdiff_basis_version desc) as dpf_version_rank
    from {{ ref("investment__gp_vault__sat_gp_detail") }}
),
pit_gp_gp_detail_scoped as (
    select
        gp_hk,
        effective_from
    from pit_gp_gp_detail_ranked
    where dpf_version_rank = 1
),
pit_gp_spine as (
    select distinct
        gp_hk,
        effective_from as as_of
    from pit_gp_gp_detail_scoped
),
pit_gp_gp_detail as (
    select
        pit_gp_spine.gp_hk as gp_hk,
        pit_gp_spine.as_of as as_of,
        max(pit_gp_gp_detail_stored.effective_from) as gp_detail_effective_from
    from pit_gp_spine
    left join pit_gp_gp_detail_scoped as pit_gp_gp_detail_stored
        on pit_gp_gp_detail_stored.gp_hk = pit_gp_spine.gp_hk
        and pit_gp_gp_detail_stored.effective_from <= pit_gp_spine.as_of
    group by pit_gp_spine.gp_hk, pit_gp_spine.as_of
),
pit_gp_joined as (
    select
        pit_gp_spine.gp_hk as gp_hk,
        pit_gp_spine.as_of as as_of,
        pit_gp_gp_detail.gp_detail_effective_from as gp_detail_effective_from
    from pit_gp_spine
    left join pit_gp_gp_detail
        on pit_gp_gp_detail.gp_hk = pit_gp_spine.gp_hk and pit_gp_gp_detail.as_of = pit_gp_spine.as_of
)

select
    cast(gp_hk as {{ dpf_type('string') }}) as gp_hk,
    cast(as_of as {{ dpf_type('date') }}) as as_of,
    cast(gp_detail_effective_from as {{ dpf_type('date') }}) as gp_detail_effective_from
from pit_gp_joined
